from typing import Annotated
from fastapi import Depends, FastAPI, Response
from fastapi.testclient import TestClient

app = FastAPI()

def modify_response() -> Response:
    return Response("Modified content", media_type="text/plain")

@app.get("/annotated")
def annotated_endpoint(response: Annotated[Response, Depends(modify_response)]):
    assert isinstance(response, Response)
    return {"response_type": type(response).__name__}

@app.get("/default")
def default_endpoint(response: Response = Depends(modify_response)):
    assert isinstance(response, Response)
    return {"response_type": type(response).__name__}

@app.get("/regular")
def regular_endpoint(response: Response):
    return {"response_type": type(response).__name__}

client = TestClient(app)

